        int ea;
        switch (pc)
        {
            case 0xF2A7: // ROM1 ADDB ,U+ ;ADD A BYTE  (T12REV3.ASM:352)
                if (!g.I(0xF2A7, 6)) return 0xF2A7;
                ea = t.U; t.U += 1;
                t.B = Add8(ref t.CC, t.B, g.Rd(ea), false);
                goto case 0xF2A9;
            case 0xF2A9: // STA WDOG  (T12REV3.ASM:353)
                if (!g.I(0xF2A9, 5)) return 0xF2A9;
                g.Wr(0xCBFF, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF2AC;
            case 0xF2AC: // EXG D,U ;SEE IF DUN  (T12REV3.ASM:354)
                if (!g.I(0xF2AC, 8)) return 0xF2AC;
                { ushort a = g.Reg(0x0, 0xF2AE), b = g.Reg(0x3, 0xF2AE); g.SetReg(0x0, b); g.SetReg(0x3, a);
                }
                goto case 0xF2AE;
            case 0xF2AE: // CMPA 2,X ;ARE WE TO NEXT PART  (T12REV3.ASM:355)
                if (!g.I(0xF2AE, 5)) return 0xF2AE;
                ea = (ushort)(t.X + 2);
                Sub8(ref t.CC, t.A, g.Rd(ea));
                goto case 0xF2B0;
            case 0xF2B0: // EXG D,U ;CHANGE BACK  (T12REV3.ASM:356)
                if (!g.I(0xF2B0, 8)) return 0xF2B0;
                { ushort a = g.Reg(0x0, 0xF2B2), b = g.Reg(0x3, 0xF2B2); g.SetReg(0x0, b); g.SetReg(0x3, a);
                }
                goto case 0xF2B2;
            case 0xF2B2: // BNE ROM1 ;NOPE  (T12REV3.ASM:357)
                if (!g.I(0xF2B2, 3)) return 0xF2B2;
                if (!Eq(t.CC)) goto case 0xF2A7;
                goto case 0xF2B4;
            case 0xF2B4: // CMPB 1,X ;EXPECTED SUM???  (T12REV3.ASM:358)
                if (!g.I(0xF2B4, 5)) return 0xF2B4;
                ea = (ushort)(t.X + 1);
                Sub8(ref t.CC, t.B, g.Rd(ea));
                goto case 0xF2B6;
            case 0xF2B6: // BNE ROMERR ;NOPE....LETS SEND OUT PROBLEM WARNING.  (T12REV3.ASM:359)
                if (!g.I(0xF2B6, 3)) return 0xF2B6;
                if (!Eq(t.CC)) return 0xF2BC;
                return 0xF2B8;
        }
        return pc;
    }

