                g.Wr(0xCBFF, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF3C7;
            case 0xF3C7: // LDA PIA0  (T12REV3.ASM:512)
                if (!g.IoI(0xF3C7, 5)) return 0xF3C7;
                t.A = g.Rd(0xC80C); t.CC = Logic8(t.CC, t.A);
                goto case 0xF3CA;
            case 0xF3CA: // BITA #2  (T12REV3.ASM:513)
                if (!g.I(0xF3CA, 2)) return 0xF3CA;
                t.CC = Logic8(t.CC, (byte)(t.A & 0x02));
                goto case 0xF3CC;
            case 0xF3CC: // BNE DIAG22 ;HOLD CONTROL UNTIL LET GO.  (T12REV3.ASM:514)
                if (!g.I(0xF3CC, 3)) return 0xF3CC;
                if (!Eq(t.CC)) goto case 0xF3C2;
                return 0xF3CE;
        }
        return pc;
    }

    /// <summary>RAMERJ: $F3CE-$F3D0.</summary>
