    /// <summary>DIAG3: $F3D1-$F3E5.</summary>
    private static ushort LF3D1_DIAG3(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0xF3D1: // DIAG3 CLR ,X+ ;CLR USABLE MEMORY  (T12REV3.ASM:516)
                if (!g.I(0xF3D1, 8)) return 0xF3D1;
                ea = t.X; t.X += 1;
                g.Rd(ea); g.Wr(ea, 0); t.CC = Clr(t.CC);
                goto case 0xF3D3;
            case 0xF3D3: // LDB #WDATA  (T12REV3.ASM:517)
                if (!g.I(0xF3D3, 2)) return 0xF3D3;
                t.B = 0x39; t.CC = Logic8(t.CC, t.B);
                goto case 0xF3D5;
            case 0xF3D5: // STB WDOG  (T12REV3.ASM:518)
                if (!g.I(0xF3D5, 5)) return 0xF3D5;
                g.Wr(0xCBFF, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF3D8;
            case 0xF3D8: // CMPX #HSTK+1  (T12REV3.ASM:519)
                if (!g.I(0xF3D8, 4)) return 0xF3D8;
                Sub16(ref t.CC, t.X, 0xBF01);
                goto case 0xF3DB;
            case 0xF3DB: // BNE DIAG3  (T12REV3.ASM:520)
                if (!g.I(0xF3DB, 3)) return 0xF3DB;
                if (!Eq(t.CC)) goto case 0xF3D1;
                goto case 0xF3DD;
            case 0xF3DD: // LDD #$A55A  (T12REV3.ASM:521)
                if (!g.I(0xF3DD, 3)) return 0xF3DD;
                t.D = 0xA55A; t.CC = Logic16(t.CC, t.D);
                goto case 0xF3E0;
            case 0xF3E0: // STD HSEED  (T12REV3.ASM:522)
                if (!g.I(0xF3E0, 5)) return 0xF3E0;
                ea = (t.DP << 8) | 0xDA;
                g.Wr16(ea, t.D); t.CC = Logic16(t.CC, t.D);
                goto case 0xF3E2;
            case 0xF3E2: // STA INDIAG ;INDICATE THAT WE'RE DIAGNOSTICS  (T12REV3.ASM:523)
                if (!g.I(0xF3E2, 4)) return 0xF3E2;
                ea = (t.DP << 8) | 0xD8;
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF3E4;
            case 0xF3E4: // BSR ZLED ;ZERO IN LED  (T12REV3.ASM:524)
                if (!g.I(0xF3E4, 7)) return 0xF3E4;
                g.PushS16(0xF3E6);
                return 0xF44D;
        }
        return pc;
    }

    /// <summary>DIAG4: $F3E6-$F3F8.</summary>
