                Sub16(ref t.CC, t.X, 0xCD00);
                goto case 0xF3F5;
            case 0xF3F5: // BHI DIAG5 ;IT WAS IN WRITABLE HALF  (T12REV3.ASM:531)
                if (!g.I(0xF3F5, 3)) return 0xF3F5;
                if (Hi(t.CC)) return 0xF3F9;
                goto case 0xF3F7;
            case 0xF3F7: // LDB #$1F  (T12REV3.ASM:532)
                if (!g.I(0xF3F7, 2)) return 0xF3F7;
                t.B = 0x1F; t.CC = Logic8(t.CC, t.B);
