    /// <summary>ZLED: $F44D-$F459.</summary>
    private static ushort LF44D_ZLED(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0xF44D: // ZLED CLR PIA1 ;ZERO IN LED INDICATES ON LAST TEST OR DUN  (T12REV3.ASM:567)
                if (!g.IoI(0xF44D, 7)) return 0xF44D;
                g.Rd(0xC80E); g.Wr(0xC80E, 0); t.CC = Clr(t.CC);
                goto case 0xF450;
            case 0xF450: // LDA #$34  (T12REV3.ASM:568)
                if (!g.I(0xF450, 2)) return 0xF450;
                t.A = 0x34; t.CC = Logic8(t.CC, t.A);
                goto case 0xF452;
            case 0xF452: // STA PIA0+1  (T12REV3.ASM:569)
                if (!g.I(0xF452, 5)) return 0xF452;
                g.Wr(0xC80D, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF455;
            case 0xF455: // INCA  (T12REV3.ASM:570)
                if (!g.I(0xF455, 2)) return 0xF455;
                t.A = Inc(ref t.CC, t.A);
                goto case 0xF456;
            case 0xF456: // STA PIA1+1  (T12REV3.ASM:571)
                if (!g.I(0xF456, 5)) return 0xF456;
                g.Wr(0xC80F, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF459;
            case 0xF459: // RTS  (T12REV3.ASM:572)
                if (!g.I(0xF459, 5)) return 0xF459;
                return g.PullS16();
        }
        return pc;
    }

