            case 0xF78B: // LDB #WDATA  (T12REV3.ASM:957)
                if (!g.I(0xF78B, 2)) return 0xF78B;
                t.B = 0x39; t.CC = Logic8(t.CC, t.B);
                goto case 0xF78D;
            case 0xF78D: // STB WDOG  (T12REV3.ASM:958)
                if (!g.I(0xF78D, 5)) return 0xF78D;
                g.Wr(0xCBFF, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF790;
            case 0xF790: // BSR SWSCN0 ;SCAN THE COCKTAIL SIDE  (T12REV3.ASM:959)
                if (!g.I(0xF790, 7)) return 0xF790;
                g.PushS16(0xF792);
                return 0xF7AE;
            case 0xF792: // LDA #$3C  (T12REV3.ASM:960)
                if (!g.I(0xF792, 2)) return 0xF792;
                t.A = 0x3C; t.CC = Logic8(t.CC, t.A);
