            case 0xF794: // STA PIA3+1  (T12REV3.ASM:961)
                if (!g.I(0xF794, 5)) return 0xF794;
                g.Wr(0xC807, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF797;
            case 0xF797: // BSR SWDISP  (T12REV3.ASM:962)
                if (!g.I(0xF797, 7)) return 0xF797;
                g.PushS16(0xF799);
                return 0xF7BE;
            case 0xF799: // JSR AVCHK ;ADVANCE PRESSED?  (T12REV3.ASM:963)
                if (!g.I(0xF799, 8)) return 0xF799;
                g.PushS16(0xF79C);
                return 0xF938;
            case 0xF79C: // BCC SWT999 ;NOPE.  (T12REV3.ASM:964)
                if (!g.I(0xF79C, 3)) return 0xF79C;
                if (!Cs(t.CC)) return 0xF7A7;
                goto case 0xF79E;
            case 0xF79E: // LDB #WDATA  (T12REV3.ASM:965)
                if (!g.I(0xF79E, 2)) return 0xF79E;
                t.B = 0x39; t.CC = Logic8(t.CC, t.B);
