                g.Wr(0xCBFF, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF7A3;
            case 0xF7A3: // DEC XTEMP  (T12REV3.ASM:967)
                if (!g.I(0xF7A3, 6)) return 0xF7A3;
                ea = (t.DP << 8) | 0xD5;
                g.Wr(ea, Dec(ref t.CC, g.Rd(ea)));
                goto case 0xF7A5;
            case 0xF7A5: // BEQ SWTBYE  (T12REV3.ASM:968)
                if (!g.I(0xF7A5, 3)) return 0xF7A5;
                if (Eq(t.CC)) return 0xF7AD;
                return 0xF7A7;
        }
        return pc;
    }

    /// <summary>SWT999: $F7A7-$F7AC.</summary>
