    /// <summary>SWSCN0: $F7AE-$F7BC.</summary>
    private static ushort LF7AE_SWSCN0(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0xF7AE: // SWSCN0 LDX ,U++ ;GET ADDRESS OF PORT  (T12REV3.ASM:975)
                if (!g.I(0xF7AE, 8)) return 0xF7AE;
                ea = t.U; t.U += 2;
                t.X = g.Rd16(ea); t.CC = Logic16(t.CC, t.X);
                goto case 0xF7B0;
            case 0xF7B0: // BEQ SWSCN5 ;DONE  (T12REV3.ASM:976)
                if (!g.I(0xF7B0, 3)) return 0xF7B0;
                if (Eq(t.CC)) return 0xF7BD;
                goto case 0xF7B2;
            case 0xF7B2: // LDY ,U++ ;GET ADDRESS TO STORE STATE  (T12REV3.ASM:977)
                if (!g.I(0xF7B2, 9)) return 0xF7B2;
                ea = t.U; t.U += 2;
                t.Y = g.Rd16(ea); t.CC = Logic16(t.CC, t.Y);
                goto case 0xF7B5;
            case 0xF7B5: // LDA ,X ;GET NEW STATE  (T12REV3.ASM:978)
                if (!g.I(0xF7B5, 4)) return 0xF7B5;
                ea = t.X;
                t.A = g.Rd(ea); t.CC = Logic8(t.CC, t.A);
                goto case 0xF7B7;
            case 0xF7B7: // EORA ,Y ;SEE WHERE DIFFERENT  (T12REV3.ASM:979)
                if (!g.I(0xF7B7, 4)) return 0xF7B7;
                ea = t.Y;
                t.A ^= g.Rd(ea); t.CC = Logic8(t.CC, t.A);
                goto case 0xF7B9;
            case 0xF7B9: // STA 1,Y ;AND SAVE AS DIFFERENCE BYTE.  (T12REV3.ASM:980)
                if (!g.I(0xF7B9, 5)) return 0xF7B9;
                ea = (ushort)(t.Y + 1);
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF7BB;
            case 0xF7BB: // BRA SWSCN0  (T12REV3.ASM:981)
                if (!g.I(0xF7BB, 3)) return 0xF7BB;
                goto case 0xF7AE;
        }
        return pc;
    }

