    /// <summary>SWDIS2: $F7CD-$F7E6.</summary>
    private static ushort LF7CD_SWDIS2(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0xF7CD: // SWDIS2 LEAU 3,U ;MOVE TO NEXT ENTRY  (T12REV3.ASM:990)
                if (!g.I(0xF7CD, 5)) return 0xF7CD;
                ea = (ushort)(t.U + 3);
                t.U = (ushort)(ea);
                goto case 0xF7CF;
            case 0xF7CF: // ASLB ;SHIFT ONE DOWN  (T12REV3.ASM:991)
                if (!g.I(0xF7CF, 2)) return 0xF7CF;
                t.B = Asl8(ref t.CC, t.B);
                goto case 0xF7D0;
            case 0xF7D0: // BCC SWDIS0  (T12REV3.ASM:992)
                if (!g.I(0xF7D0, 3)) return 0xF7D0;
                if (!Cs(t.CC)) return 0xF7C7;
                goto case 0xF7D2;
            case 0xF7D2: // LDB #WDATA  (T12REV3.ASM:993)
                if (!g.I(0xF7D2, 2)) return 0xF7D2;
                t.B = 0x39; t.CC = Logic8(t.CC, t.B);
                goto case 0xF7D4;
            case 0xF7D4: // STB WDOG  (T12REV3.ASM:994)
                if (!g.I(0xF7D4, 5)) return 0xF7D4;
                g.Wr(0xCBFF, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF7D7;
            case 0xF7D7: // LEAY 2,Y ;TO NEXT BYTE  (T12REV3.ASM:995)
                if (!g.I(0xF7D7, 5)) return 0xF7D7;
                ea = (ushort)(t.Y + 2);
                t.Y = (ushort)(ea);
                t.CC = Set(t.CC, Z, t.Y == 0);
                goto case 0xF7D9;
            case 0xF7D9: // CMPY #SW3SCI ;PAST TABLE  (T12REV3.ASM:996)
                if (!g.I(0xF7D9, 5)) return 0xF7D9;
                Sub16(ref t.CC, t.Y, 0xA100);
                goto case 0xF7DD;
            case 0xF7DD: // BHI SWDIS9 ;YEP..DONE  (T12REV3.ASM:997)
                if (!g.I(0xF7DD, 3)) return 0xF7DD;
                if (Hi(t.CC)) return 0xF7E7;
                goto case 0xF7DF;
            case 0xF7DF: // BRA SWDIS4 ;YEP...FULL SCAN  (T12REV3.ASM:1000)
                if (!g.I(0xF7DF, 3)) return 0xF7DF;
                return 0xF7C5;
            case 0xF7E1: // CMPY #SW3SCN ;NOPE..DONE WITH NORMAL SWITCHES??  (T12REV3.ASM:1001)
                if (!g.I(0xF7E1, 5)) return 0xF7E1;
                Sub16(ref t.CC, t.Y, 0xA0FC);
                goto case 0xF7E5;
            case 0xF7E5: // BLS SWDIS4 ;NOT DONE  (T12REV3.ASM:1002)
                if (!g.I(0xF7E5, 3)) return 0xF7E5;
                if (!Hi(t.CC)) return 0xF7C5;
                return 0xF7E7;
        }
        return pc;
    }

