                goto case 0xF7EC;
            case 0xF7EC: // STA SOUND ;BRING SOUND LINES HIGH IN ANTICIPATION  (T12REV3.ASM:1007)
                if (!g.I(0xF7EC, 5)) return 0xF7EC;
                g.Wr(0xC80E, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xF7EF;
            case 0xF7EF: // EORB ,Y ;INVERT THE BIT  (T12REV3.ASM:1008)
                if (!g.I(0xF7EF, 4)) return 0xF7EF;
                ea = t.Y;
                t.B ^= g.Rd(ea); t.CC = Logic8(t.CC, t.B);
                goto case 0xF7F1;
            case 0xF7F1: // STB ,Y ;AND MAKE THAT THE NEW STATE  (T12REV3.ASM:1009)
                if (!g.I(0xF7F1, 4)) return 0xF7F1;
                ea = t.Y;
                g.Wr(ea, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF7F3;
            case 0xF7F3: // LDB ,S ;RESTORE MASK  (T12REV3.ASM:1010)
                if (!g.I(0xF7F3, 4)) return 0xF7F3;
                ea = t.S;
                t.B = g.Rd(ea); t.CC = Logic8(t.CC, t.B);
                goto case 0xF7F5;
            case 0xF7F5: // BITB ,Y ;WHICH WAY DID IT GO  (T12REV3.ASM:1011)
                if (!g.I(0xF7F5, 4)) return 0xF7F5;
                ea = t.Y;
                t.CC = Logic8(t.CC, (byte)(t.B & g.Rd(ea)));
