                if (!g.I(0xF7F7, 3)) return 0xF7F7;
                if (!Eq(t.CC)) return 0xF820;
                goto case 0xF7F9;
            case 0xF7F9: // LDB 2,U ;HEIGHT  (T12REV3.ASM:1013)
                if (!g.I(0xF7F9, 5)) return 0xF7F9;
                ea = (ushort)(t.U + 2);
                t.B = g.Rd(ea); t.CC = Logic8(t.CC, t.B);
                goto case 0xF7FB;
            case 0xF7FB: // BEQ SWNOAC  (T12REV3.ASM:1014)
                if (!g.I(0xF7FB, 3)) return 0xF7FB;
                if (Eq(t.CC)) return 0xF845;
                goto case 0xF7FD;
            case 0xF7FD: // LDA #$40 ;X  (T12REV3.ASM:1015)
                if (!g.I(0xF7FD, 2)) return 0xF7FD;
                t.A = 0x40; t.CC = Logic8(t.CC, t.A);
                goto case 0xF7FF;
            case 0xF7FF: // TFR D,X ;MAKE IT CURSOR  (T12REV3.ASM:1016)
                if (!g.I(0xF7FF, 6)) return 0xF7FF;
                t.X = t.D;
                goto case 0xF801;
