                if (!g.I(0xF801, 2)) return 0xF801;
                t.B = 0x39; t.CC = Logic8(t.CC, t.B);
                goto case 0xF803;
            case 0xF803: // STB WDOG  (T12REV3.ASM:1018)
                if (!g.I(0xF803, 5)) return 0xF803;
                g.Wr(0xCBFF, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF806;
            case 0xF806: // LDD #$3006!DMAFIX ;;Fixme was: LDD #$3006!XDMAFIX  (T12REV3.ASM:1019)
                if (!g.I(0xF806, 3)) return 0xF806;
                t.D = 0x3402; t.CC = Logic16(t.CC, t.D);
                goto case 0xF809;
            case 0xF809: // STD $CA06 ;DMA X and Y SIZE  (T12REV3.ASM:1021)
                if (!g.I(0xF809, 6)) return 0xF809;
                g.Wr16(0xCA06, t.D); t.CC = Logic16(t.CC, t.D);
                goto case 0xF80C;
            case 0xF80C: // STX $CA04 ;DMA DESTINATION  (T12REV3.ASM:1022)
                if (!g.I(0xF80C, 6)) return 0xF80C;
                g.Wr16(0xCA04, t.X); t.CC = Logic16(t.CC, t.X);
