                goto case 0xF811;
            case 0xF811: // STB $CA01 ;DMA CONSTANT  (T12REV3.ASM:1025)
                if (!g.I(0xF811, 5)) return 0xF811;
                g.Wr(0xCA01, t.B); t.CC = Logic8(t.CC, t.B);
                goto case 0xF814;
            case 0xF814: // LDB #$12 ;CONSTANT SUBSTITUTION, WRITE BLOCK  (T12REV3.ASM:1026)
                if (!g.I(0xF814, 2)) return 0xF814;
                t.B = 0x12; t.CC = Logic8(t.CC, t.B);
                goto case 0xF816;
            case 0xF816: // STB $CA00 ;AND LET THE DMA GO!!!!  (T12REV3.ASM:1027)
                if (!g.I(0xF816, 5)) return 0xF816;
                g.Wr(0xCA00, t.B); t.CC = Logic8(t.CC, t.B);
