                goto case 0xF81E;
            case 0xF81E: // PULS B,X,PC  (T12REV3.ASM:1031)
                if (!g.I(0xF81E, 10)) return 0xF81E;
                t.B = g.PullS();
                t.X = g.PullS16();
                return g.PullS16();
