                if (!g.I(0xFAD8, 5)) return 0xFAD8;
                ea = (t.DP << 8) | 0xDC;
                g.Wr16(ea, t.D); t.CC = Logic16(t.CC, t.D);
                goto case 0xFADA;
            case 0xFADA: // LDA BCDTMP+2  (T12REV3.ASM:1383)
                if (!g.I(0xFADA, 4)) return 0xFADA;
                ea = (t.DP << 8) | 0xE8;
                t.A = g.Rd(ea); t.CC = Logic8(t.CC, t.A);
                goto case 0xFADC;
            case 0xFADC: // STA BCDR+2  (T12REV3.ASM:1384)
                if (!g.I(0xFADC, 4)) return 0xFADC;
                ea = (t.DP << 8) | 0xDE;
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xFADE;
            case 0xFADE: // INC BCDN+2 ;NBR OF SUCCESSFULL SUBTRACTIONS GOES TO THE ANSWER  (T12REV3.ASM:1385)
                if (!g.I(0xFADE, 6)) return 0xFADE;
                ea = (t.DP << 8) | 0xE1;
                g.Wr(ea, Inc(ref t.CC, g.Rd(ea)));
                goto case 0xFAE0;
            case 0xFAE0: // BRA BDVCMP ;CHACK AGAIN FOR SUBTRACTION (MAXIMUM LOOPS = 9)  (T12REV3.ASM:1386)
                if (!g.I(0xFAE0, 3)) return 0xFAE0;
                return 0xFAD0;
        }
        return pc;
    }

    /// <summary>BCDNEG: $FAE2-$FB01.</summary>
    private static ushort LFAE2_BCDNEG(Gen g, ushort pc)
    {
        var t = g.T;
        int ea;
        switch (pc)
        {
            case 0xFAE2: // BCDNEG PSHS Y  (T12REV3.ASM:1393)
                if (!g.I(0xFAE2, 7)) return 0xFAE2;
                g.PushS16(t.Y);
