            case 0xFAE4: // LDB #3 ;COMPLIMENT THE BCD NUMBER  (T12REV3.ASM:1394)
                if (!g.I(0xFAE4, 2)) return 0xFAE4;
                t.B = 0x03; t.CC = Logic8(t.CC, t.B);
                goto case 0xFAE6;
            case 0xFAE6: // .2S LDA #$99 ;DIGIT BY DIGIT (THERE MUST BE A FASTER WAY!)  (T12REV3.ASM:1395)
                if (!g.I(0xFAE6, 2)) return 0xFAE6;
