                goto case 0xFAE8;
            case 0xFAE8: // SUBA ,-Y  (T12REV3.ASM:1396)
                if (!g.I(0xFAE8, 6)) return 0xFAE8;
                t.Y -= 1; ea = t.Y;
                t.A = Sub8(ref t.CC, t.A, g.Rd(ea));
                goto case 0xFAEA;
            case 0xFAEA: // STA ,Y  (T12REV3.ASM:1397)
                if (!g.I(0xFAEA, 4)) return 0xFAEA;
                ea = t.Y;
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xFAEC;
