                t.B = Dec(ref t.CC, t.B);
                goto case 0xFAED;
            case 0xFAED: // BNE .2S  (T12REV3.ASM:1399)
                if (!g.I(0xFAED, 3)) return 0xFAED;
                if (!Eq(t.CC)) goto case 0xFAE6;
                goto case 0xFAEF;
            case 0xFAEF: // LDY ,S ;RESTORE REG.Y  (T12REV3.ASM:1400)
                if (!g.I(0xFAEF, 6)) return 0xFAEF;
                ea = t.S;
                t.Y = g.Rd16(ea); t.CC = Logic16(t.CC, t.Y);
                goto case 0xFAF2;
            case 0xFAF2: // LDB #3 ;6 BCD DIGITS TO SUBTRACT  (T12REV3.ASM:1401)
                if (!g.I(0xFAF2, 2)) return 0xFAF2;
                t.B = 0x03; t.CC = Logic8(t.CC, t.B);
                goto case 0xFAF4;
            case 0xFAF4: // ORCC #$01 ;SET CARRY TO ADD 1  (T12REV3.ASM:1402)
                if (!g.I(0xFAF4, 3)) return 0xFAF4;
                t.CC |= 0x01;
                goto case 0xFAF6;
