                t.A = g.Rd(ea); t.CC = Logic8(t.CC, t.A);
                goto case 0xFAF8;
            case 0xFAF8: // ADCA #0  (T12REV3.ASM:1404)
                if (!g.I(0xFAF8, 2)) return 0xFAF8;
                t.A = Add8(ref t.CC, t.A, 0x00, true);
                goto case 0xFAFA;
            case 0xFAFA: // DAA  (T12REV3.ASM:1405)
                if (!g.I(0xFAFA, 2)) return 0xFAFA;
                t.A = Daa(ref t.CC, t.A);
                goto case 0xFAFB;
            case 0xFAFB: // STA ,-Y  (T12REV3.ASM:1406)
                if (!g.I(0xFAFB, 6)) return 0xFAFB;
                t.Y -= 1; ea = t.Y;
                g.Wr(ea, t.A); t.CC = Logic8(t.CC, t.A);
                goto case 0xFAFD;
            case 0xFAFD: // DECB  (T12REV3.ASM:1407)
                if (!g.I(0xFAFD, 2)) return 0xFAFD;
                t.B = Dec(ref t.CC, t.B);
                goto case 0xFAFE;
            case 0xFAFE: // BNE .1S  (T12REV3.ASM:1408)
                if (!g.I(0xFAFE, 3)) return 0xFAFE;
                if (!Eq(t.CC)) goto case 0xFAF6;
                goto case 0xFB00;
            case 0xFB00: // PULS Y,PC  (T12REV3.ASM:1409)
                if (!g.I(0xFB00, 9)) return 0xFB00;
                t.Y = g.PullS16();
                return g.PullS16();
        }
        return pc;
    }

